package org.sleepwell.app;
import android.content.*;import android.os.SystemClock;import android.provider.Settings;import java.util.*;import java.util.concurrent.*;
/** One worker serializes all rule creation/state/removal/expiry and private-journal writes. */
final class TrackingDndRuntime {
 interface Factory{TrackingDndOwner.Port create(Context c);}static Factory providers=TrackingDndAndroid::new;static final Map<TrackingDndSettings.Factory,Job> jobs=new IdentityHashMap<>();static synchronized Job get(Context c){TrackingDndSettings.Factory f=TrackingDndSettings.factory;return jobs.computeIfAbsent(f,k->new Job(c.getApplicationContext(),new TrackingDndSettings(f.open(c)),providers.create(c.getApplicationContext())));}
 static boolean requested(Context c){try{return TrackingDndSettings.open(c).enabled();}catch(RuntimeException invalid){return false;}}
 static int boot(Context c){return Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,0);}static void recover(Context c){Job job=get(c);job.submit(()->{if(job.settings.touchedBefore())job.owner.recover(TrackingService::ownsDnd,boot(job.app),SystemClock.elapsedRealtime());},false);}
 static void active(Context c,String run,boolean requested){Job job=get(c);job.submit(()->job.owner.start(run,requested&&job.settings.enabled(),SystemClock.elapsedRealtime(),boot(job.app),()->TrackingService.ownsDnd(run)),false);}
 static void renew(Context c,String run){Job job=get(c);job.submit(()->{if(!job.settings.enabled())job.owner.stop(run);else job.owner.renew(run,SystemClock.elapsedRealtime(),boot(job.app),()->TrackingService.ownsDnd(run));},false);}
 static void stop(Context c,String run){if(run==null||run.isEmpty())return;Job job=get(c);job.submit(()->job.owner.stop(run),false);}
 static final class State{final boolean busy,enabled,access,exact;final TrackingDndLease lease;final String error;State(boolean busy,boolean enabled,boolean access,boolean exact,TrackingDndLease lease,String error){this.busy=busy;this.enabled=enabled;this.access=access;this.exact=exact;this.lease=lease;this.error=error;}}
 interface Action{void run();}
 static final class Job{final Context app;final TrackingDndSettings settings;final TrackingDndOwner.Port port;final TrackingDndOwner owner;final ExecutorService worker=Executors.newSingleThreadExecutor();volatile State state=new State(false,false,false,false,null,"");int pending;
 Job(Context c,TrackingDndSettings s,TrackingDndOwner.Port p){app=c;settings=s;port=p;owner=new TrackingDndOwner(s,p,()->UUID.randomUUID().toString());}
 synchronized void submit(Action action,boolean inspect){pending++;State old=state;state=new State(true,old.enabled,old.access,old.exact,old.lease,old.error);worker.execute(()->{String error="";boolean access=state.access,exact=state.exact;TrackingDndLease lease=state.lease;boolean enabled=state.enabled;try{action.run();if(inspect){access=port.access();exact=port.exact();}enabled=settings.enabled();lease=settings.read();error=settings.error();}catch(RuntimeException failure){error=failure.getMessage()==null?"Tracking DND needs attention.":failure.getMessage();try{settings.error(error);enabled=settings.enabled();lease=settings.read();}catch(RuntimeException statusFailure){error+=" Owned-rule status could not be saved.";}}synchronized(this){pending--;state=new State(pending>0,enabled,access,exact,lease,error);}});}
 void inspect(){submit(()->{},true);}void preference(boolean enabled){submit(()->{settings.enabled(enabled);if(!enabled){TrackingDndLease lease=settings.read();if(lease!=null)owner.stop(lease.run);settings.error("");}},true);}void cleanup(){submit(()->{settings.enabled(false);owner.recover(run->false,boot(app),SystemClock.elapsedRealtime());settings.error("");},true);}
 }
 static void drain(TrackingDndSettings.Factory f)throws Exception{Job j;synchronized(TrackingDndRuntime.class){j=jobs.get(f);}if(j!=null)j.worker.submit(()->{}).get(10,TimeUnit.SECONDS);}static synchronized void forget(TrackingDndSettings.Factory f){Job j=jobs.get(f);if(j!=null){if(j.state.busy)throw new IllegalStateException("DND work remains active");jobs.remove(f);j.worker.shutdown();}}
 private TrackingDndRuntime(){}
}
